class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)

        # Helper function to check if index i is a peak
        def is_peak(i):
            if i <= 0 or i >= n - 1:
                return False
            return nums[i] > nums[i - 1] and nums[i] > nums[i + 1]

        # Build initial peak array
        peaks = [0] * n
        for i in range(1, n - 1):
            if is_peak(i):
                peaks[i] = 1

        # Build prefix sum array for efficient range queries
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + peaks[i]

        answer = []

        for query in queries:
            if query[0] == 1:
                # Type 1: Count peaks in range [l, r]
                l, r = query[1], query[2]
                # Peaks can only exist from index 1 to n-2
                # So we need peaks in range [max(1, l), min(n-2, r)]
                left = max(1, l)
                right = min(n - 2, r)

                if left > right:
                    answer.append(0)
                else:
                    count = prefix[right + 1] - prefix[left]
                    answer.append(count)
            else:
                # Type 2: Update nums[index] to val
                index, val = query[1], query[2]
                nums[index] = val

                # Update peaks for affected indices (index-1, index, index+1)
                for i in range(max(1, index - 1), min(n - 1, index + 2)):
                    old_peak = peaks[i]
                    new_peak = 1 if is_peak(i) else 0

                    if old_peak != new_peak:
                        peaks[i] = new_peak
                        # Update prefix sum from i+1 onwards
                        for j in range(i + 1, n + 1):
                            prefix[j] += new_peak - old_peak

        return answer

class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        def xor_score(arr):
            """Calculate XOR score of an array"""
            if len(arr) == 1:
                return arr[0]

            current = arr[:]
            while len(current) > 1:
                new_arr = []
                for i in range(len(current) - 1):
                    new_arr.append(current[i] ^ current[i + 1])
                current = new_arr
            return current[0]

        results = []

        for l, r in queries:
            max_score = 0

            # Try all subarrays in nums[l..r]
            for start in range(l, r + 1):
                for end in range(start, r + 1):
                    subarray = nums[start:end + 1]
                    score = xor_score(subarray)
                    max_score = max(max_score, score)

            results.append(max_score)

        return results

