    def findKthSmallest(self, coins: List[int], k: int) -> int:
        from math import gcd
        from functools import reduce

        def lcm(a, b):
            return a * b // gcd(a, b)

        def count_amounts(x):
            """Count how many valid amounts are <= x"""
            n = len(coins)
            total = 0

            # Inclusion-exclusion principle
            # Iterate through all non-empty subsets
            for mask in range(1, 1 << n):
                subset = []
                for i in range(n):
                    if mask & (1 << i):
                        subset.append(coins[i])

                # Calculate LCM of this subset
                subset_lcm = reduce(lcm, subset)
                count = x // subset_lcm

                # Add or subtract based on subset size (inclusion-exclusion)
                if len(subset) % 2 == 1:
                    total += count
                else:
                    total -= count

            return total

        # Binary search for the k-th smallest amount
        left, right = 1, k * min(coins)

        while left < right:
            mid = (left + right) // 2
            if count_amounts(mid) < k:
                left = mid + 1
            else:
                right = mid

        return left

class Solution:
    def numberOfSubarrays(self, nums: List[int]) -> int:
        count = 0
        n = len(nums)

        for i in range(n):
            max_val = nums[i]
            for j in range(i, n):
                max_val = max(max_val, nums[j])
                # Check if first element equals last element and both equal max
                if nums[i] == nums[j] == max_val:
                    count += 1

        return count
